function toolComplex(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Complex Number Lab</h3></div>
    <div class="p-5 space-y-4 max-w-md">
      <div class="grid grid-cols-2 gap-3">
        <div><label class="text-xs font-medium">Real a</label><input type="number" id="cx-a" value="3" class="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
        <div><label class="text-xs font-medium">Imag b</label><input type="number" id="cx-b" value="4" class="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
      </div>
      <div class="result-box" id="cx-out"></div>
    </div></div>`;
  const calc = () => {
    const a = +$("#cx-a").value, b = +$("#cx-b").value;
    const mod = Math.sqrt(a*a+b*b), arg = Math.atan2(b,a)*180/Math.PI;
    $("#cx-out").innerHTML = `z = ${a} ${b>=0?"+":"−"} ${Math.abs(b)}i<br>|z| = <strong>${mod.toFixed(4)}</strong><br>arg(z) = <strong>${arg.toFixed(2)}°</strong><br>Polar: ${mod.toFixed(3)}(cos ${arg.toFixed(1)}° + i sin ${arg.toFixed(1)}°)`;
  };
  ["cx-a","cx-b"].forEach(id => $(`#${id}`).addEventListener("input", calc)); calc();
}

function toolVector(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">2D Vector Lab</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4 max-w-md">
      <div class="grid grid-cols-2 gap-2">
        <div><label class="text-xs">Aₓ</label><input type="number" id="vec-ax" value="3" class="mt-1 w-full px-2 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
        <div><label class="text-xs">Aᵧ</label><input type="number" id="vec-ay" value="4" class="mt-1 w-full px-2 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
        <div><label class="text-xs">Bₓ</label><input type="number" id="vec-bx" value="1" class="mt-1 w-full px-2 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
        <div><label class="text-xs">Bᵧ</label><input type="number" id="vec-by" value="0" class="mt-1 w-full px-2 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
      </div>
      <div class="result-box" id="vec-out"></div>
    </div><div class="canvas-wrap"><canvas id="vec-canvas" width="320" height="240"></canvas></div></div></div>`;
  const canvas=$("#vec-canvas"), ctx=canvas.getContext("2d");
  const calc=()=>{
    const ax=+$("#vec-ax").value,ay=+$("#vec-ay").value,bx=+$("#vec-bx").value,by=+$("#vec-by").value;
    const magA=Math.hypot(ax,ay), magB=Math.hypot(bx,by), dot=ax*bx+ay*by;
    const cos=magA*magB?dot/(magA*magB):0, ang=Math.acos(Math.max(-1,Math.min(1,cos)))*180/Math.PI;
    $("#vec-out").innerHTML=`|A| = <strong>${magA.toFixed(3)}</strong><br>|B| = <strong>${magB.toFixed(3)}</strong><br>A·B = <strong>${dot.toFixed(3)}</strong><br>θ = <strong>${ang.toFixed(1)}°</strong>`;
    const isDark=document.documentElement.classList.contains("dark");
    ctx.clearRect(0,0,canvas.width,canvas.height);
    const ox=160, oy=120, sc=25;
    ctx.strokeStyle=isDark?"#334155":"#e2e8f0"; ctx.beginPath(); ctx.moveTo(20,oy); ctx.lineTo(300,oy); ctx.moveTo(ox,20); ctx.lineTo(ox,220); ctx.stroke();
    const arr=(x,y,col)=>{ctx.strokeStyle=col;ctx.fillStyle=col;ctx.lineWidth=2.5;ctx.beginPath();ctx.moveTo(ox,oy);ctx.lineTo(ox+x*sc,oy-y*sc);ctx.stroke();};
    arr(ax,ay,isDark?"#38bdf8":"#0284c7"); arr(bx,by,isDark?"#a78bfa":"#7c3aed");
  };
  ["vec-ax","vec-ay","vec-bx","vec-by"].forEach(id=>$(`#${id}`).addEventListener("input",calc)); calc();
}

function toolIntegral(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Area Under Curve</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4">
      <div class="flex gap-2 flex-wrap">
        ${["x^2","sin x","e^x"].map((f,i)=>`<button class="int-fn px-3 py-1.5 text-xs font-semibold rounded-lg ${i===0?"bg-brand-600 text-white":"bg-slate-100 dark:bg-slate-800"}" data-f="${f}">${f}</button>`).join("")}
      </div>
      <div class="slider-group"><label>a <span id="int-a-val">0</span></label><input type="range" id="int-a" min="-2" max="2" value="0" step="0.1"/></div>
      <div class="slider-group"><label>b <span id="int-b-val">2</span></label><input type="range" id="int-b" min="-2" max="4" value="2" step="0.1"/></div>
      <div class="result-box" id="int-out"></div>
    </div><div class="canvas-wrap"><canvas id="int-canvas" width="360" height="220"></canvas></div></div></div>`;
  let fn="x^2";
  const fMap={"x^2":x=>x*x,"sin x":x=>Math.sin(x),"e^x":x=>Math.exp(x)};
  const canvas=$("#int-canvas"), ctx=canvas.getContext("2d");
  const calc=()=>{
    const a=+$("#int-a").value, b=+$("#int-b").value;
    $("#int-a-val").textContent=a; $("#int-b-val").textContent=b;
    const f=fMap[fn]; let sum=0, N=200;
    for(let i=0;i<N;i++){const x=a+(b-a)*(i+0.5)/N; sum+=f(x);}
    const area=sum*(b-a)/N;
    $("#int-out").innerHTML=`∫<sub>a</sub><sup>b</sup> ${fn} dx ≈ <strong>${area.toFixed(4)}</strong>`;
    const isDark=document.documentElement.classList.contains("dark");
    ctx.clearRect(0,0,canvas.width,canvas.height);
    const ox=40, oy=180, sx=60, sy=30;
    ctx.strokeStyle=isDark?"#334155":"#e2e8f0"; ctx.beginPath(); ctx.moveTo(20,oy); ctx.lineTo(340,oy); ctx.moveTo(ox,20); ctx.lineTo(ox,200); ctx.stroke();
    // fill area
    ctx.fillStyle=isDark?"rgba(56,189,248,0.25)":"rgba(2,132,199,0.2)";
    ctx.beginPath(); ctx.moveTo(ox+a*sx, oy);
    for(let i=0;i<=50;i++){const x=a+(b-a)*i/50; ctx.lineTo(ox+x*sx, oy-f(x)*sy);}
    ctx.lineTo(ox+b*sx, oy); ctx.closePath(); ctx.fill();
    ctx.strokeStyle=isDark?"#38bdf8":"#0284c7"; ctx.lineWidth=2; ctx.beginPath();
    for(let i=0;i<=80;i++){const x=-0.5+i*0.05; const px=ox+x*sx, py=oy-f(x)*sy; if(i===0)ctx.moveTo(px,py); else ctx.lineTo(px,py);}
    ctx.stroke();
  };
  $$(".int-fn").forEach(btn=>btn.addEventListener("click",()=>{
    fn=btn.dataset.f;
    $$(".int-fn").forEach(b=>{b.classList.toggle("bg-brand-600",b===btn);b.classList.toggle("text-white",b===btn);b.classList.toggle("bg-slate-100",b!==btn);});
    calc();
  }));
  ["int-a","int-b"].forEach(id=>$(`#${id}`).addEventListener("input",calc)); calc();
}

function toolRadioactive(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Radioactive Decay</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4">
      <div class="slider-group"><label>N₀ <span id="rad-n0-val">1000</span></label><input type="range" id="rad-n0" min="100" max="5000" value="1000" step="100"/></div>
      <div class="slider-group"><label>Half-life (s) <span id="rad-t12-val">10</span></label><input type="range" id="rad-t12" min="1" max="30" value="10" step="0.5"/></div>
      <div class="slider-group"><label>t (s) <span id="rad-t-val">10</span></label><input type="range" id="rad-t" min="0" max="60" value="10" step="0.5"/></div>
      <div class="result-box" id="rad-out"></div></div>
      <div class="canvas-wrap"><canvas id="rad-canvas" width="400" height="260"></canvas></div></div></div>`;
  const canvas = $("#rad-canvas"), ctx = canvas.getContext("2d");
  const calc = () => {
    const N0 = +$("#rad-n0").value, t12 = +$("#rad-t12").value, t = +$("#rad-t").value;
    $("#rad-n0-val").textContent = N0; $("#rad-t12-val").textContent = t12; $("#rad-t-val").textContent = t;
    const lambda = 0.693/t12, N = N0 * Math.exp(-lambda*t);
    $("#rad-out").innerHTML = `λ = <strong>${lambda.toFixed(4)} s⁻¹</strong><br>N(t) = <strong>${N.toFixed(1)}</strong>`;
    ctx.clearRect(0,0,canvas.width,canvas.height);
    const isDark = document.documentElement.classList.contains("dark");
    ctx.strokeStyle = isDark ? "#fb923c" : "#ea580c"; ctx.lineWidth = 2; ctx.beginPath();
    for (let i=0;i<canvas.width;i++) {
      const tt = i/canvas.width*60, yy = N0*Math.exp(-lambda*tt);
      const py = canvas.height - 20 - yy/N0*(canvas.height-40);
      if (i===0) ctx.moveTo(i,py); else ctx.lineTo(i,py);
    }
    ctx.stroke();
  };
  ["rad-n0","rad-t12","rad-t"].forEach(id => $(`#${id}`).addEventListener("input", calc)); calc();
}

function toolGasLaw(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Ideal Gas Law</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4 max-w-md">
      <div class="slider-group"><label>n (mol) <span id="gas-n-val">1</span></label><input type="range" id="gas-n" min="0.1" max="5" value="1" step="0.1"/></div>
      <div class="slider-group"><label>T (K) <span id="gas-t-val">300</span></label><input type="range" id="gas-t" min="100" max="600" value="300"/></div>
      <div class="slider-group"><label>V (L) <span id="gas-v-val">22.4</span></label><input type="range" id="gas-v" min="1" max="50" value="22.4" step="0.1"/></div>
      <div class="result-box" id="gas-out"></div>
    </div><div class="canvas-wrap"><canvas id="gas-canvas" width="280" height="200"></canvas></div></div></div>`;
  const canvas=$("#gas-canvas"), ctx=canvas.getContext("2d");
  const R=0.0821;
  const calc=()=>{
    const n=+$("#gas-n").value, T=+$("#gas-t").value, V=+$("#gas-v").value;
    $("#gas-n-val").textContent=n; $("#gas-t-val").textContent=T; $("#gas-v-val").textContent=V;
    const P=n*R*T/V;
    $("#gas-out").innerHTML=`P = nRT/V = <strong>${P.toFixed(3)} atm</strong>`;
    const isDark=document.documentElement.classList.contains("dark");
    ctx.clearRect(0,0,canvas.width,canvas.height);
    // container
    const scale=Math.sqrt(V/22.4);
    const w=80*scale, h=100*scale;
    ctx.strokeStyle=isDark?"#94a3b8":"#64748b"; ctx.lineWidth=2;
    ctx.strokeRect(100, 40+(100-h), w, h);
    // dots for molecules
    ctx.fillStyle=isDark?"#38bdf8":"#0284c7";
    const dots=Math.min(30, Math.round(n*12));
    for(let i=0;i<dots;i++){
      const x=100+10+Math.random()*(w-20), y=40+(100-h)+10+Math.random()*(h-20);
      ctx.beginPath(); ctx.arc(x,y,3,0,Math.PI*2); ctx.fill();
    }
  };
  ["gas-n","gas-t","gas-v"].forEach(id=>$(`#${id}`).addEventListener("input",calc)); calc();
}


function toolAtwood(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Atwood Machine</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4 max-w-md">
      <div class="slider-group"><label>m₁ (kg) <span id="at-m1-val">5</span></label><input type="range" id="at-m1" min="0.5" max="20" value="5" step="0.1"/></div>
      <div class="slider-group"><label>m₂ (kg) <span id="at-m2-val">3</span></label><input type="range" id="at-m2" min="0.5" max="20" value="3" step="0.1"/></div>
      <div class="result-box" id="at-out"></div>
    </div><div class="canvas-wrap"><canvas id="at-canvas" width="320" height="260"></canvas></div></div></div>`;
  const canvas = $("#at-canvas"), ctx = canvas.getContext("2d");
  const calc = () => {
    const m1=+$("#at-m1").value, m2=+$("#at-m2").value, g=9.8;
    $("#at-m1-val").textContent=m1; $("#at-m2-val").textContent=m2;
    const a=((m1-m2)*g)/(m1+m2), T=(2*m1*m2*g)/(m1+m2);
    $("#at-out").innerHTML=`a = <strong>${a.toFixed(3)} m/s²</strong> (${m1>m2?"m₁ down":"m₂ down"})<br>T = <strong>${T.toFixed(3)} N</strong>`;
    const isDark = document.documentElement.classList.contains("dark");
    ctx.clearRect(0,0,canvas.width,canvas.height);
    const cx=160, top=40;
    ctx.strokeStyle=isDark?"#94a3b8":"#64748b"; ctx.lineWidth=3;
    ctx.beginPath(); ctx.arc(cx, top, 18, 0, Math.PI*2); ctx.stroke(); // pulley
    ctx.beginPath(); ctx.moveTo(cx-18, top); ctx.lineTo(cx-50, 200); ctx.moveTo(cx+18, top); ctx.lineTo(cx+50, 200); ctx.stroke();
    const h1=120+(m1-m2)*8, h2=120-(m1-m2)*8;
    ctx.fillStyle=isDark?"#38bdf8":"#0284c7"; ctx.fillRect(cx-70, h1, 40, 40);
    ctx.fillStyle=isDark?"#a78bfa":"#7c3aed"; ctx.fillRect(cx+30, h2, 40, 40);
    ctx.fillStyle=isDark?"#e2e8f0":"#1e293b"; ctx.font="12px Inter,sans-serif";
    ctx.fillText("m₁", cx-60, h1+25); ctx.fillText("m₂", cx+40, h2+25);
  };
  ["at-m1","at-m2"].forEach(id=>$(`#${id}`).addEventListener("input",calc)); calc();
}

function toolInclined(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Inclined Plane</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4 max-w-md">
      <div class="slider-group"><label>θ (°) <span id="inc-th-val">30</span></label><input type="range" id="inc-th" min="0" max="60" value="30"/></div>
      <div class="slider-group"><label>μ <span id="inc-mu-val">0.2</span></label><input type="range" id="inc-mu" min="0" max="1" value="0.2" step="0.01"/></div>
      <div class="result-box" id="inc-out"></div>
    </div><div class="canvas-wrap"><canvas id="inc-canvas" width="420" height="260"></canvas></div></div></div>`;
  const canvas = $("#inc-canvas"), ctx = canvas.getContext("2d");
  const calc = () => {
    const thDeg = +$("#inc-th").value, th = thDeg * Math.PI / 180, mu = +$("#inc-mu").value, g = 9.8;
    $("#inc-th-val").textContent = thDeg; $("#inc-mu-val").textContent = mu;
    const aDown = g * (Math.sin(th) - mu * Math.cos(th));
    const aUp = g * (Math.sin(th) + mu * Math.cos(th));
    const aSmooth = g * Math.sin(th);
    $("#inc-out").innerHTML = `Smooth a = <strong>${aSmooth.toFixed(3)} m/s²</strong><br>Down (friction) a = <strong>${aDown.toFixed(3)} m/s²</strong><br>Up (retardation) a = <strong>${aUp.toFixed(3)} m/s²</strong>`;
    const isDark = document.documentElement.classList.contains("dark");
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const baseY = 220, baseX = 40, L = 300;
    const x2 = baseX + L * Math.cos(th), y2 = baseY - L * Math.sin(th);
    ctx.strokeStyle = isDark ? "#94a3b8" : "#475569"; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(baseX, baseY); ctx.lineTo(baseX + L, baseY); ctx.lineTo(x2, y2); ctx.closePath(); ctx.stroke();
    // block on incline
    const mid = 0.55;
    const bx = baseX + L * mid * Math.cos(th), by = baseY - L * mid * Math.sin(th);
    ctx.save();
    ctx.translate(bx, by); ctx.rotate(-th);
    ctx.fillStyle = isDark ? "#38bdf8" : "#0284c7";
    ctx.fillRect(-18, -24, 36, 24);
    ctx.restore();
    ctx.fillStyle = isDark ? "#e2e8f0" : "#334155"; ctx.font = "13px Inter,sans-serif";
    ctx.fillText("θ = " + thDeg + "°", baseX + 50, baseY - 10);
  };
  ["inc-th", "inc-mu"].forEach(id => $(`#${id}`).addEventListener("input", calc)); calc();
}

function toolCollision(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">1D Elastic Collision</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4 max-w-md">
      <div class="grid grid-cols-2 gap-3">
        <div><label class="text-xs">m₁</label><input type="number" id="col-m1" value="2" class="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
        <div><label class="text-xs">u₁</label><input type="number" id="col-u1" value="5" class="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
        <div><label class="text-xs">m₂</label><input type="number" id="col-m2" value="3" class="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
        <div><label class="text-xs">u₂</label><input type="number" id="col-u2" value="0" class="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
      </div>
      <div class="result-box" id="col-out"></div>
    </div><div class="canvas-wrap"><canvas id="col-canvas" width="400" height="160"></canvas></div></div></div>`;
  const canvas=$("#col-canvas"), ctx=canvas.getContext("2d");
  const calc=()=>{
    const m1=+$("#col-m1").value,m2=+$("#col-m2").value,u1=+$("#col-u1").value,u2=+$("#col-u2").value;
    const v1=((m1-m2)*u1+2*m2*u2)/(m1+m2), v2=((m2-m1)*u2+2*m1*u1)/(m1+m2);
    $("#col-out").innerHTML=`v₁ = <strong>${v1.toFixed(4)}</strong><br>v₂ = <strong>${v2.toFixed(4)}</strong>`;
    const isDark=document.documentElement.classList.contains("dark");
    ctx.clearRect(0,0,canvas.width,canvas.height);
    const y=80;
    ctx.strokeStyle=isDark?"#475569":"#cbd5e1"; ctx.beginPath(); ctx.moveTo(20,y+30); ctx.lineTo(380,y+30); ctx.stroke();
    const r1=12+m1*2, r2=12+m2*2;
    ctx.fillStyle=isDark?"#38bdf8":"#0284c7"; ctx.beginPath(); ctx.arc(100,y,r1,0,Math.PI*2); ctx.fill();
    ctx.fillStyle=isDark?"#a78bfa":"#7c3aed"; ctx.beginPath(); ctx.arc(280,y,r2,0,Math.PI*2); ctx.fill();
    ctx.fillStyle=isDark?"#e2e8f0":"#334155"; ctx.font="11px Inter,sans-serif";
    ctx.fillText("m₁", 92, y+4); ctx.fillText("m₂", 272, y+4);
    // velocity arrows
    ctx.strokeStyle=isDark?"#fbbf24":"#d97706"; ctx.lineWidth=2;
    const drawArr=(x,dir,lab)=>{ctx.beginPath();ctx.moveTo(x,y-r1-15);ctx.lineTo(x+dir*30,y-r1-15);ctx.stroke();ctx.fillText(lab,x,y-r1-20);};
    if(Math.abs(v1)>0.01) drawArr(100, v1>0?1:-1, "v₁");
    if(Math.abs(v2)>0.01) drawArr(280, v2>0?1:-1, "v₂");
  };
  ["col-m1","col-m2","col-u1","col-u2"].forEach(id=>$(`#${id}`).addEventListener("input",calc)); calc();
}

function toolYDSE(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Young's Double Slit</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4 max-w-md">
      <div class="slider-group"><label>λ (nm) <span id="yd-l-val">600</span></label><input type="range" id="yd-l" min="400" max="700" value="600"/></div>
      <div class="slider-group"><label>d (mm) <span id="yd-d-val">0.5</span></label><input type="range" id="yd-d" min="0.1" max="2" value="0.5" step="0.05"/></div>
      <div class="slider-group"><label>D (m) <span id="yd-D-val">1</span></label><input type="range" id="yd-D" min="0.5" max="3" value="1" step="0.1"/></div>
      <div class="result-box" id="yd-out"></div>
    </div><div class="canvas-wrap"><canvas id="yd-canvas" width="360" height="220"></canvas></div></div></div>`;
  const canvas=$("#yd-canvas"), ctx=canvas.getContext("2d");
  const calc=()=>{
    const lam=+$("#yd-l").value*1e-9, d=+$("#yd-d").value*1e-3, D=+$("#yd-D").value;
    $("#yd-l-val").textContent=$("#yd-l").value; $("#yd-d-val").textContent=$("#yd-d").value; $("#yd-D-val").textContent=D;
    const beta=lam*D/d;
    $("#yd-out").innerHTML=`Fringe width β = <strong>${(beta*1000).toFixed(4)} mm</strong>`;
    const isDark=document.documentElement.classList.contains("dark");
    ctx.clearRect(0,0,canvas.width,canvas.height);
    // slits
    ctx.fillStyle=isDark?"#e2e8f0":"#1e293b";
    ctx.fillRect(40,80,6,20); ctx.fillRect(40,120,6,20);
    // screen
    ctx.fillRect(300,40,6,140);
    // fringe pattern on screen
    for(let i=0;i<12;i++){
      const bright=i%2===0;
      ctx.fillStyle=bright?(isDark?"#fbbf24":"#f59e0b"):(isDark?"#1e293b":"#f1f5f9");
      ctx.fillRect(306, 50+i*10, 20, 10);
    }
    ctx.strokeStyle=isDark?"#38bdf8":"#0284c7"; ctx.lineWidth=1;
    ctx.beginPath(); ctx.moveTo(46,90); ctx.lineTo(300,100); ctx.moveTo(46,130); ctx.lineTo(300,100); ctx.stroke();
  };
  ["yd-l","yd-d","yd-D"].forEach(id=>$(`#${id}`).addEventListener("input",calc)); calc();
}

function toolBohr(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Bohr Model (Hydrogen)</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4 max-w-md">
      <div class="slider-group"><label>n <span id="bohr-n-val">1</span></label><input type="range" id="bohr-n" min="1" max="6" value="1" step="1"/></div>
      <div class="result-box" id="bohr-out"></div>
    </div><div class="canvas-wrap"><canvas id="bohr-canvas" width="300" height="300"></canvas></div></div></div>`;
  const canvas=$("#bohr-canvas"), ctx=canvas.getContext("2d");
  const calc=()=>{
    const n=+$("#bohr-n").value;
    $("#bohr-n-val").textContent=n;
    const E=-13.6/(n*n), r=0.529*n*n;
    $("#bohr-out").innerHTML=`Eₙ = <strong>${E.toFixed(4)} eV</strong><br>rₙ = <strong>${r.toFixed(4)} Å</strong>`;
    const isDark=document.documentElement.classList.contains("dark");
    ctx.clearRect(0,0,canvas.width,canvas.height);
    const cx=150, cy=150;
    ctx.fillStyle=isDark?"#fbbf24":"#f59e0b"; ctx.beginPath(); ctx.arc(cx,cy,8,0,Math.PI*2); ctx.fill();
    for(let k=1;k<=6;k++){
      const rad=20+k*18;
      ctx.strokeStyle=k===n?(isDark?"#38bdf8":"#0284c7"):(isDark?"#334155":"#e2e8f0");
      ctx.lineWidth=k===n?2.5:1;
      ctx.beginPath(); ctx.arc(cx,cy,rad,0,Math.PI*2); ctx.stroke();
    }
    const rad=20+n*18;
    ctx.fillStyle=isDark?"#a78bfa":"#7c3aed";
    ctx.beginPath(); ctx.arc(cx+rad, cy, 6, 0, Math.PI*2); ctx.fill();
  };
  $("#bohr-n").addEventListener("input",calc); calc();
}

function toolMolality(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Solution Concentrations</h3></div>
    <div class="p-5 space-y-4 max-w-md">
      <div><label class="text-sm">Mass solute (g)</label><input type="number" id="mol-ms" value="10" class="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
      <div><label class="text-sm">Molar mass (g/mol)</label><input type="number" id="mol-M" value="58.5" class="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
      <div><label class="text-sm">Volume solution (L)</label><input type="number" id="mol-V" value="0.5" step="0.01" class="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
      <div><label class="text-sm">Mass solvent (kg)</label><input type="number" id="mol-ws" value="0.5" step="0.01" class="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
      <div class="result-box" id="mol-out"></div>
    </div></div>`;
  const calc = () => {
    const ms=+$("#mol-ms").value, M=+$("#mol-M").value, V=+$("#mol-V").value, ws=+$("#mol-ws").value;
    const n=ms/M, molarity=n/V, molality=n/ws;
    $("#mol-out").innerHTML=`n = <strong>${n.toFixed(4)} mol</strong><br>Molarity = <strong>${molarity.toFixed(4)} M</strong><br>Molality = <strong>${molality.toFixed(4)} m</strong>`;
  };
  ["mol-ms","mol-M","mol-V","mol-ws"].forEach(id=>$(`#${id}`).addEventListener("input",calc)); calc();
}

function toolLimits(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Limit Explorer</h3><p class="text-xs text-slate-500 mt-1">lim x→a of (x²−a²)/(x−a)</p></div>
    <div class="p-5 space-y-4 max-w-md">
      <div class="slider-group"><label>a <span id="lim-a-val">2</span></label><input type="range" id="lim-a" min="-5" max="5" value="2" step="0.1"/></div>
      <div class="slider-group"><label>x approach δ <span id="lim-d-val">0.01</span></label><input type="range" id="lim-d" min="0.0001" max="0.5" value="0.01" step="0.0001"/></div>
      <div class="result-box" id="lim-out"></div>
    </div></div>`;
  const calc = () => {
    const a=+$("#lim-a").value, d=+$("#lim-d").value;
    $("#lim-a-val").textContent=a; $("#lim-d-val").textContent=d;
    const f = x => (x*x - a*a)/(x-a);
    const left=f(a-d), right=f(a+d);
    $("#lim-out").innerHTML=`f(a−δ) ≈ <strong>${left.toFixed(6)}</strong><br>f(a+δ) ≈ <strong>${right.toFixed(6)}</strong><br>Expected limit = <strong>${(2*a).toFixed(4)}</strong> (= 2a)`;
  };
  ["lim-a","lim-d"].forEach(id=>$(`#${id}`).addEventListener("input",calc)); calc();
}

function toolDet3(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">3×3 Determinant</h3></div>
    <div class="p-5 space-y-4 max-w-md">
      <div class="grid grid-cols-3 gap-2" id="det3-grid">
        ${[1,0,0,0,1,0,0,0,1].map((v,i)=>`<input type="number" id="d3-${i}" value="${v}" class="px-2 py-1.5 rounded border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm text-center"/>`).join("")}
      </div>
      <div class="result-box" id="d3-out"></div>
    </div></div>`;
  const calc = () => {
    const a=[...Array(9)].map((_,i)=>+$("#d3-"+i).value);
    const det=a[0]*(a[4]*a[8]-a[5]*a[7])-a[1]*(a[3]*a[8]-a[5]*a[6])+a[2]*(a[3]*a[7]-a[4]*a[6]);
    $("#d3-out").innerHTML=`|A| = <strong>${det}</strong>`;
  };
  for(let i=0;i<9;i++) $("#d3-"+i).addEventListener("input",calc); calc();
}

function toolBinomProb(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Binomial Probability</h3></div>
    <div class="p-5 space-y-4 max-w-md">
      <div class="slider-group"><label>n <span id="bp-n-val">10</span></label><input type="range" id="bp-n" min="1" max="30" value="10"/></div>
      <div class="slider-group"><label>p <span id="bp-p-val">0.5</span></label><input type="range" id="bp-p" min="0.05" max="0.95" value="0.5" step="0.05"/></div>
      <div class="slider-group"><label>r <span id="bp-r-val">5</span></label><input type="range" id="bp-r" min="0" max="10" value="5"/></div>
      <div class="result-box" id="bp-out"></div>
    </div></div>`;
  const fact=n=>{let r=1;for(let i=2;i<=n;i++)r*=i;return r;};
  const C=(n,r)=>fact(n)/(fact(r)*fact(n-r));
  const calc = () => {
    const n=+$("#bp-n").value, p=+$("#bp-p").value, r=Math.min(+$("#bp-r").value,n);
    $("#bp-n-val").textContent=n; $("#bp-p-val").textContent=p; $("#bp-r-val").textContent=r; $("#bp-r").max=n;
    const P=C(n,r)*Math.pow(p,r)*Math.pow(1-p,n-r);
    $("#bp-out").innerHTML=`P(X=${r}) = <strong>${P.toFixed(6)}</strong><br>μ = np = <strong>${(n*p).toFixed(2)}</strong><br>σ² = npq = <strong>${(n*p*(1-p)).toFixed(2)}</strong>`;
  };
  ["bp-n","bp-p","bp-r"].forEach(id=>$(`#${id}`).addEventListener("input",calc)); calc();
}

function toolHalfAdder(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Half & Full Adder</h3></div>
    <div class="p-5 space-y-4 max-w-md">
      <div class="flex gap-2">
        <button class="ha-mode active px-3 py-1.5 text-xs font-semibold rounded-lg bg-brand-600 text-white" data-mode="half">Half Adder</button>
        <button class="ha-mode px-3 py-1.5 text-xs font-semibold rounded-lg bg-slate-100 dark:bg-slate-800" data-mode="full">Full Adder</button>
      </div>
      <div class="flex gap-4 items-center">
        <label class="flex items-center gap-2 text-sm"><input type="checkbox" id="ha-a"/> A</label>
        <label class="flex items-center gap-2 text-sm"><input type="checkbox" id="ha-b"/> B</label>
        <label class="flex items-center gap-2 text-sm" id="ha-cin-wrap"><input type="checkbox" id="ha-cin"/> Cin</label>
      </div>
      <div class="result-box" id="ha-out"></div>
    </div></div>`;
  let mode="half";
  const calc = () => {
    const A=+$("#ha-a").checked, B=+$("#ha-b").checked, Cin=+$("#ha-cin").checked;
    $("#ha-cin-wrap").style.display = mode==="full" ? "" : "none";
    let S, C;
    if (mode==="half") { S=A^B; C=A&B; }
    else { S=A^B^Cin; C=(A&B)|(B&Cin)|(A&Cin); }
    $("#ha-out").innerHTML=`Sum S = <strong>${S}</strong><br>Carry C = <strong>${C}</strong>`;
  };
  $$(".ha-mode").forEach(btn=>btn.addEventListener("click",()=>{
    mode=btn.dataset.mode;
    $$(".ha-mode").forEach(b=>{b.classList.toggle("bg-brand-600",b===btn);b.classList.toggle("text-white",b===btn);b.classList.toggle("bg-slate-100",b!==btn);b.classList.toggle("dark:bg-slate-800",b!==btn);});
    calc();
  }));
  ["ha-a","ha-b","ha-cin"].forEach(id=>$(`#${id}`).addEventListener("change",calc)); calc();
}


function toolCapacitor(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Capacitor Energy</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4 max-w-md">
      <div class="slider-group"><label>C (μF) <span id="cap-c-val">10</span></label><input type="range" id="cap-c" min="1" max="100" value="10"/></div>
      <div class="slider-group"><label>V (V) <span id="cap-v-val">12</span></label><input type="range" id="cap-v" min="1" max="100" value="12"/></div>
      <div class="result-box" id="cap-out"></div>
    </div><div class="canvas-wrap"><canvas id="cap-canvas" width="280" height="200"></canvas></div></div></div>`;
  const canvas=$("#cap-canvas"), ctx=canvas.getContext("2d");
  const calc=()=>{
    const C=+$("#cap-c").value*1e-6, V=+$("#cap-v").value;
    $("#cap-c-val").textContent=$("#cap-c").value; $("#cap-v-val").textContent=V;
    const Q=C*V, U=0.5*C*V*V;
    $("#cap-out").innerHTML=`Q = <strong>${(Q*1e6).toFixed(2)} μC</strong><br>U = <strong>${(U*1e6).toFixed(2)} μJ</strong>`;
    const isDark=document.documentElement.classList.contains("dark");
    ctx.clearRect(0,0,canvas.width,canvas.height);
    const gap=Math.max(8, 40-V/5);
    ctx.strokeStyle=isDark?"#e2e8f0":"#1e293b"; ctx.lineWidth=4;
    ctx.beginPath(); ctx.moveTo(100,40); ctx.lineTo(100,160); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(100+gap+20,40); ctx.lineTo(100+gap+20,160); ctx.stroke();
    ctx.lineWidth=1; ctx.beginPath(); ctx.moveTo(60,100); ctx.lineTo(100,100); ctx.moveTo(120+gap,100); ctx.lineTo(220,100); ctx.stroke();
    ctx.font="12px Inter,sans-serif"; ctx.fillStyle=isDark?"#94a3b8":"#64748b";
    ctx.fillText("+Q", 80, 35); ctx.fillText("−Q", 130+gap, 35);
  };
  ["cap-c","cap-v"].forEach(id=>$(`#${id}`).addEventListener("input",calc)); calc();
}
function toolPhotoelectric(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Photoelectric Effect</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4 max-w-md">
      <div class="slider-group"><label>f (×10¹⁴ Hz) <span id="pe-f-val">8</span></label><input type="range" id="pe-f" min="1" max="20" value="8" step="0.1"/></div>
      <div class="slider-group"><label>φ (eV) <span id="pe-w-val">2.5</span></label><input type="range" id="pe-w" min="1" max="6" value="2.5" step="0.1"/></div>
      <div class="result-box" id="pe-out"></div>
    </div><div class="canvas-wrap"><canvas id="pe-canvas" width="320" height="200"></canvas></div></div></div>`;
  const canvas=$("#pe-canvas"), ctx=canvas.getContext("2d");
  const h=4.14e-15;
  const calc=()=>{
    const f=+$("#pe-f").value*1e14, w=+$("#pe-w").value;
    $("#pe-f-val").textContent=$("#pe-f").value; $("#pe-w-val").textContent=w;
    const E=h*f, K=E-w, f0=w/h;
    $("#pe-out").innerHTML=`Photon E = <strong>${E.toFixed(3)} eV</strong><br>K<sub>max</sub> = <strong>${K>0?K.toFixed(3)+" eV":"0 (no emission)"}</strong><br>f₀ = <strong>${(f0/1e14).toFixed(2)}×10¹⁴ Hz</strong>`;
    const isDark=document.documentElement.classList.contains("dark");
    ctx.clearRect(0,0,canvas.width,canvas.height);
    // metal surface
    ctx.fillStyle=isDark?"#475569":"#94a3b8"; ctx.fillRect(40,120,160,40);
    ctx.fillStyle=isDark?"#e2e8f0":"#1e293b"; ctx.font="11px Inter,sans-serif"; ctx.fillText("metal", 90, 145);
    // photon wave
    ctx.strokeStyle=isDark?"#fbbf24":"#d97706"; ctx.lineWidth=2; ctx.beginPath();
    for(let i=0;i<80;i++) ctx.lineTo(20+i, 60+8*Math.sin(i/4)); ctx.stroke();
    ctx.fillText("hν", 50, 50);
    // electron if emitted
    if(K>0){
      ctx.fillStyle=isDark?"#38bdf8":"#0284c7";
      ctx.beginPath(); ctx.arc(240, 80, 8, 0, Math.PI*2); ctx.fill();
      ctx.fillText("e⁻", 250, 85);
    }
  };
  ["pe-f","pe-w"].forEach(id=>$(`#${id}`).addEventListener("input",calc)); calc();
}
function toolSpring(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Spring Force & Energy</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4 max-w-md">
      <div class="slider-group"><label>k (N/m) <span id="sp-k-val">100</span></label><input type="range" id="sp-k" min="10" max="500" value="100"/></div>
      <div class="slider-group"><label>x (m) <span id="sp-x-val">0.1</span></label><input type="range" id="sp-x" min="-0.4" max="0.4" value="0.1" step="0.01"/></div>
      <div class="result-box" id="sp-out"></div>
    </div><div class="canvas-wrap"><canvas id="sp-canvas" width="480" height="200"></canvas></div></div></div>`;
  const canvas = $("#sp-canvas"), ctx = canvas.getContext("2d");
  const calc = () => {
    const k = +$("#sp-k").value, x = +$("#sp-x").value;
    $("#sp-k-val").textContent = k; $("#sp-x-val").textContent = x;
    $("#sp-out").innerHTML = `F = −kx = <strong>${(-k*x).toFixed(2)} N</strong><br>U = ½kx² = <strong>${(0.5*k*x*x).toFixed(4)} J</strong>`;
    const isDark = document.documentElement.classList.contains("dark");
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const mid = canvas.height / 2, wall = 40, eq = 240, massX = eq + x * 300;
    ctx.strokeStyle = isDark ? "#64748b" : "#94a3b8"; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(wall, 30); ctx.lineTo(wall, canvas.height - 30); ctx.stroke();
    ctx.strokeStyle = isDark ? "#34d399" : "#059669"; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(wall, mid);
    const coils = 12, span = massX - 24 - wall;
    for (let i = 0; i <= coils; i++) {
      const sx = wall + (span * i) / coils, sy = mid + ((i % 2 === 0) ? -14 : 14);
      ctx.lineTo(sx, sy);
    }
    ctx.lineTo(massX - 20, mid); ctx.stroke();
    ctx.fillStyle = isDark ? "#fbbf24" : "#f59e0b";
    ctx.fillRect(massX - 20, mid - 18, 40, 36);
    // equilibrium dashed line
    ctx.setLineDash([4, 4]); ctx.strokeStyle = isDark ? "#475569" : "#cbd5e1";
    ctx.beginPath(); ctx.moveTo(eq, 20); ctx.lineTo(eq, canvas.height - 20); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = isDark ? "#94a3b8" : "#64748b"; ctx.font = "11px Inter,sans-serif";
    ctx.fillText("eq", eq - 8, canvas.height - 8);
  };
  ["sp-k", "sp-x"].forEach(id => $(`#${id}`).addEventListener("input", calc)); calc();
}
function toolSnell(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Snell's Law & Critical Angle</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4 max-w-md">
      <div class="slider-group"><label>μ₁ <span id="sn-m1-val">1.5</span></label><input type="range" id="sn-m1" min="1" max="2.5" value="1.5" step="0.05"/></div>
      <div class="slider-group"><label>μ₂ <span id="sn-m2-val">1.0</span></label><input type="range" id="sn-m2" min="1" max="2.5" value="1.0" step="0.05"/></div>
      <div class="slider-group"><label>i (°) <span id="sn-i-val">30</span></label><input type="range" id="sn-i" min="0" max="90" value="30"/></div>
      <div class="result-box" id="sn-out"></div>
    </div><div class="canvas-wrap"><canvas id="sn-canvas" width="360" height="280"></canvas></div></div></div>`;
  const canvas=$("#sn-canvas"), ctx=canvas.getContext("2d");
  const calc=()=>{
    const m1=+$("#sn-m1").value, m2=+$("#sn-m2").value, iDeg=+$("#sn-i").value, i=iDeg*Math.PI/180;
    $("#sn-m1-val").textContent=m1; $("#sn-m2-val").textContent=m2; $("#sn-i-val").textContent=iDeg;
    const s=m1*Math.sin(i)/m2;
    let rText, r=null;
    if(s>1) rText="TIR";
    else { r=Math.asin(s); rText=(r*180/Math.PI).toFixed(1)+"°"; }
    const ic=m1>m2?(Math.asin(m2/m1)*180/Math.PI).toFixed(1)+"°":"N/A";
    $("#sn-out").innerHTML=`r = <strong>${rText}</strong><br>Critical angle i_c = <strong>${ic}</strong>`;
    const isDark=document.documentElement.classList.contains("dark");
    ctx.clearRect(0,0,canvas.width,canvas.height);
    const ox=180, oy=140;
    ctx.strokeStyle=isDark?"#475569":"#94a3b8"; ctx.lineWidth=1;
    ctx.beginPath(); ctx.moveTo(20,oy); ctx.lineTo(340,oy); ctx.stroke(); // interface
    ctx.setLineDash([4,4]); ctx.beginPath(); ctx.moveTo(ox,20); ctx.lineTo(ox,260); ctx.stroke(); ctx.setLineDash([]);
    // incident ray
    const len=90;
    ctx.strokeStyle=isDark?"#38bdf8":"#0284c7"; ctx.lineWidth=2.5;
    ctx.beginPath(); ctx.moveTo(ox-len*Math.sin(i), oy-len*Math.cos(i)); ctx.lineTo(ox,oy); ctx.stroke();
    if(r!=null){
      ctx.strokeStyle=isDark?"#a78bfa":"#7c3aed";
      ctx.beginPath(); ctx.moveTo(ox,oy); ctx.lineTo(ox+len*Math.sin(r), oy+len*Math.cos(r)); ctx.stroke();
    } else {
      // reflected for TIR
      ctx.strokeStyle=isDark?"#fbbf24":"#d97706";
      ctx.beginPath(); ctx.moveTo(ox,oy); ctx.lineTo(ox+len*Math.sin(i), oy-len*Math.cos(i)); ctx.stroke();
    }
    ctx.fillStyle=isDark?"#94a3b8":"#64748b"; ctx.font="11px Inter,sans-serif";
    ctx.fillText("μ₁", 30, oy-10); ctx.fillText("μ₂", 30, oy+20);
  };
  ["sn-m1","sn-m2","sn-i"].forEach(id=>$(`#${id}`).addEventListener("input",calc)); calc();
}
function toolCombinatorics(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">nPr & nCr</h3></div>
    <div class="p-5 space-y-4 max-w-md">
      <div class="slider-group"><label>n <span id="pc-n-val">10</span></label><input type="range" id="pc-n" min="1" max="20" value="10"/></div>
      <div class="slider-group"><label>r <span id="pc-r-val">3</span></label><input type="range" id="pc-r" min="0" max="10" value="3"/></div>
      <div class="result-box" id="pc-out"></div>
    </div></div>`;
  const fact=n=>{let r=1n; for(let i=2n;i<=BigInt(n);i++)r*=i; return r;};
  const calc=()=>{
    const n=+$("#pc-n").value; let r=+$("#pc-r").value; if(r>n)r=n;
    $("#pc-n-val").textContent=n; $("#pc-r-val").textContent=r; $("#pc-r").max=n;
    const nPr = fact(n)/fact(n-r), nCr = nPr/fact(r);
    $("#pc-out").innerHTML=`P(${n},${r}) = <strong>${nPr.toString()}</strong><br>C(${n},${r}) = <strong>${nCr.toString()}</strong>`;
  };
  ["pc-n","pc-r"].forEach(id=>$(`#${id}`).addEventListener("input",calc)); calc();
}


function toolOhms(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Ohm's Law Lab</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4 max-w-md">
      <div class="slider-group"><label>V (volts) <span id="oh-v-val">12</span></label><input type="range" id="oh-v" min="1" max="24" value="12" step="0.5"/></div>
      <div class="slider-group"><label>R (Ω) <span id="oh-r-val">100</span></label><input type="range" id="oh-r" min="1" max="1000" value="100"/></div>
      <div class="result-box" id="oh-out"></div>
    </div><div class="canvas-wrap"><canvas id="oh-canvas" width="420" height="220"></canvas></div></div></div>`;
  const canvas = $("#oh-canvas"), ctx = canvas.getContext("2d");
  const calc = () => {
    const V = +$("#oh-v").value, R = +$("#oh-r").value;
    $("#oh-v-val").textContent = V; $("#oh-r-val").textContent = R;
    const I = V / R, P = V * I;
    $("#oh-out").innerHTML = `I = V/R = <strong>${I.toFixed(4)} A</strong><br>P = VI = <strong>${P.toFixed(4)} W</strong>`;
    const isDark = document.documentElement.classList.contains("dark");
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const c = isDark ? "#e2e8f0" : "#1e293b";
    ctx.strokeStyle = c; ctx.fillStyle = c; ctx.lineWidth = 2;
    // simple loop: battery left, resistor right
    const x0 = 60, y0 = 50, x1 = 320, y1 = 160;
    ctx.beginPath();
    ctx.moveTo(x0, y0); ctx.lineTo(x1, y0); ctx.lineTo(x1, y1); ctx.lineTo(x0, y1); ctx.closePath(); ctx.stroke();
    // battery symbol
    ctx.beginPath(); ctx.moveTo(x0 - 8, y0 + 30); ctx.lineTo(x0 + 8, y0 + 30); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(x0 - 14, y0 + 45); ctx.lineTo(x0 + 14, y0 + 45); ctx.stroke();
    ctx.font = "12px Inter,sans-serif"; ctx.fillText("V = " + V + " V", x0 - 20, y0 + 70);
    // resistor zig-zag
    ctx.beginPath();
    let zx = x1 - 40, zy = y0;
    ctx.moveTo(zx - 30, zy);
    for (let i = 0; i < 6; i++) ctx.lineTo(zx - 30 + i * 10, zy + ((i % 2) ? 12 : -12));
    ctx.lineTo(zx + 30, zy); ctx.stroke();
    ctx.fillText("R = " + R + " Ω", x1 - 50, y0 - 12);
    ctx.fillText("I = " + I.toFixed(3) + " A", (x0 + x1) / 2 - 30, y1 + 25);
  };
  ["oh-v", "oh-r"].forEach(id => $(`#${id}`).addEventListener("input", calc)); calc();
}
