function toolProjectile2(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Projectile Motion</h3></div>
    <div class="p-5 space-y-4 max-w-md">
      <div class="slider-group"><label>u (m/s) <span id="pj-u-val">20</span></label><input type="range" id="pj-u" min="1" max="50" value="20"/></div>
      <div class="slider-group"><label>θ (°) <span id="pj-th-val">45</span></label><input type="range" id="pj-th" min="0" max="90" value="45"/></div>
      <div class="result-box" id="pj-out"></div>
    </div></div>`;
  const calc=()=>{
    const u=+$("#pj-u").value, th=+$("#pj-th").value*Math.PI/180, g=9.8;
    $("#pj-u-val").textContent=u; $("#pj-th-val").textContent=$("#pj-th").value;
    const ux=u*Math.cos(th), uy=u*Math.sin(th), T=2*uy/g, R=ux*T, H=uy*uy/(2*g);
    $("#pj-out").innerHTML=`uₓ = <strong>${ux.toFixed(2)}</strong> · uᵧ = <strong>${uy.toFixed(2)}</strong><br>T = <strong>${T.toFixed(3)} s</strong><br>R = <strong>${R.toFixed(2)} m</strong><br>H_max = <strong>${H.toFixed(2)} m</strong>`;
  };
  ["pj-u","pj-th"].forEach(id=>$(`#${id}`).addEventListener("input",calc)); calc();
}
function toolVectorAdd(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">2D Vector Addition</h3></div>
    <div class="p-5 grid lg:grid-cols-2 gap-6"><div class="space-y-4 max-w-md">
      <div class="grid grid-cols-2 gap-3">
        <div><label class="text-xs">Aₓ</label><input type="number" id="va-ax" value="3" class="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
        <div><label class="text-xs">Aᵧ</label><input type="number" id="va-ay" value="4" class="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
        <div><label class="text-xs">Bₓ</label><input type="number" id="va-bx" value="1" class="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
        <div><label class="text-xs">Bᵧ</label><input type="number" id="va-by" value="2" class="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-sm"/></div>
      </div>
      <div class="result-box" id="va-out"></div>
    </div><div class="canvas-wrap"><canvas id="va-canvas" width="400" height="300"></canvas></div></div></div>`;
  const canvas = $("#va-canvas"), ctx = canvas.getContext("2d");
  const arrow = (x0, y0, x1, y1, color) => {
    ctx.strokeStyle = color; ctx.fillStyle = color; ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
    const ang = Math.atan2(y1 - y0, x1 - x0);
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x1 - 10 * Math.cos(ang - 0.4), y1 - 10 * Math.sin(ang - 0.4));
    ctx.lineTo(x1 - 10 * Math.cos(ang + 0.4), y1 - 10 * Math.sin(ang + 0.4));
    ctx.closePath(); ctx.fill();
  };
  const calc = () => {
    const ax = +$("#va-ax").value, ay = +$("#va-ay").value, bx = +$("#va-bx").value, by = +$("#va-by").value;
    const rx = ax + bx, ry = ay + by, mag = Math.hypot(rx, ry), ang = Math.atan2(ry, rx) * 180 / Math.PI;
    $("#va-out").innerHTML = `R = <strong>(${rx.toFixed(2)}, ${ry.toFixed(2)})</strong><br>|R| = <strong>${mag.toFixed(3)}</strong><br>θ = <strong>${ang.toFixed(1)}°</strong>`;
    const isDark = document.documentElement.classList.contains("dark");
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const ox = canvas.width / 2, oy = canvas.height / 2, sc = 28;
    ctx.strokeStyle = isDark ? "#334155" : "#e2e8f0"; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(20, oy); ctx.lineTo(canvas.width - 20, oy); ctx.moveTo(ox, 20); ctx.lineTo(ox, canvas.height - 20); ctx.stroke();
    arrow(ox, oy, ox + ax * sc, oy - ay * sc, isDark ? "#38bdf8" : "#0284c7");
    arrow(ox + ax * sc, oy - ay * sc, ox + rx * sc, oy - ry * sc, isDark ? "#34d399" : "#059669");
    arrow(ox, oy, ox + rx * sc, oy - ry * sc, isDark ? "#f472b6" : "#db2777");
    ctx.font = "12px Inter,sans-serif";
    ctx.fillStyle = isDark ? "#94a3b8" : "#64748b";
    ctx.fillText("A", ox + ax * sc / 2, oy - ay * sc / 2 - 8);
    ctx.fillText("B", ox + ax * sc + bx * sc / 2, oy - ay * sc - by * sc / 2 - 8);
    ctx.fillText("R", ox + rx * sc / 2 + 8, oy - ry * sc / 2);
  };
  ["va-ax", "va-ay", "va-bx", "va-by"].forEach(id => $(`#${id}`).addEventListener("input", calc)); calc();
}
function toolTruth(el) {
  el.innerHTML = `<div class="tool-panel"><div class="tool-header"><h3 class="font-semibold">Logic Gate Explorer</h3></div>
    <div class="p-5 space-y-4 max-w-md">
      <div class="flex flex-wrap gap-2" id="tg-gates">
        ${["AND","OR","NAND","NOR","XOR","XNOR"].map(g=>`<button class="tg-btn px-3 py-1.5 text-xs font-semibold rounded-lg bg-slate-100 dark:bg-slate-800" data-g="${g}">${g}</button>`).join("")}
      </div>
      <div class="flex gap-6 items-center">
        <label class="flex items-center gap-2 text-sm"><input type="checkbox" id="tg-a"/> A</label>
        <label class="flex items-center gap-2 text-sm"><input type="checkbox" id="tg-b"/> B</label>
      </div>
      <div class="result-box" id="tg-out"></div>
    </div></div>`;
  let gate="AND";
  const ops={AND:(a,b)=>a&b,OR:(a,b)=>a|b,NAND:(a,b)=>+(!(a&b)),NOR:(a,b)=>+(!(a|b)),XOR:(a,b)=>a^b,XNOR:(a,b)=>+(!(a^b))};
  const calc=()=>{
    const a=+$("#tg-a").checked,b=+$("#tg-b").checked, out=ops[gate](a,b);
    $("#tg-out").innerHTML=`${gate}(${a},${b}) = <strong class="text-2xl">${out}</strong>`;
  };
  $$(".tg-btn").forEach(btn=>btn.addEventListener("click",()=>{
    gate=btn.dataset.g;
    $$(".tg-btn").forEach(b=>{b.classList.toggle("bg-brand-600",b===btn);b.classList.toggle("text-white",b===btn);});
    calc();
  }));
  ["tg-a","tg-b"].forEach(id=>$(`#${id}`).addEventListener("change",calc));
  $$(".tg-btn")[0].click();
}

/* ============================================================
   INIT
   ============================================================ */
function init() {
  applyTheme();
  $("#fav-count").textContent = state.favorites.length;

  $$(".subject-tab").forEach(btn => btn.addEventListener("click", () => {
    state.subject = btn.dataset.subject; state.unit = null; state.subtopic = null; state.view = "formulas";
    $$(".subject-tab").forEach(b => b.classList.toggle("active", b === btn));
    renderNavTree(); renderContent();
  }));

  $$(".class-btn").forEach(btn => btn.addEventListener("click", () => {
    state.classLevel = btn.dataset.class; state.unit = null; state.subtopic = null;
    $$(".class-btn").forEach(b => b.classList.toggle("active", b === btn));
    renderNavTree(); if (state.view === "formulas") renderContent();
  }));

  $("#btn-theme").addEventListener("click", () => { state.theme = state.theme === "dark" ? "light" : "dark"; applyTheme(); });
  $("#btn-menu").addEventListener("click", openSidebarMobile);
  $("#sidebar-overlay").addEventListener("click", closeSidebarMobile);
  $("#btn-favorites").addEventListener("click", () => { state.view = "favorites"; renderContent(); closeSidebarMobile(); });
  $("#btn-tools").addEventListener("click", () => { state.view = "tools"; renderContent(); closeSidebarMobile(); });

  $$(".goto-subject").forEach(btn => btn.addEventListener("click", () => {
    state.subject = btn.dataset.goto; state.unit = null; state.subtopic = null; state.view = "formulas";
    $$(".subject-tab").forEach(b => b.classList.toggle("active", b.dataset.subject === state.subject));
    renderNavTree(); renderContent();
  }));

  const searchHandler = debounce(() => {
    const q = $("#search-input").value.trim();
    if (!q) { state.view = state.unit ? "formulas" : "home"; state.searchQuery = ""; renderContent(); return; }
    state.searchQuery = q; state.view = "search"; renderContent();
  }, 200);
  $("#search-input").addEventListener("input", searchHandler);
  $("#search-input").addEventListener("input", () => {
    const clearBtn = $("#search-clear");
    if (clearBtn) clearBtn.classList.toggle("hidden", !$("#search-input").value);
  });
  const clearBtn = $("#search-clear");
  if (clearBtn) clearBtn.addEventListener("click", () => {
    $("#search-input").value = "";
    clearBtn.classList.add("hidden");
    state.searchQuery = "";
    state.view = state.unit ? "formulas" : "home";
    renderContent();
    $("#search-input").focus();
  });

  document.addEventListener("keydown", e => {
    if ((e.metaKey || e.ctrlKey) && e.key === "k") { e.preventDefault(); $("#search-input").focus(); }
    if (e.key === "Escape") { closeSidebarMobile(); $("#search-input").blur(); }
  });

  if (state.lastViewed) {
    state.subject = state.lastViewed.subject || "physics";
    state.classLevel = state.lastViewed.classLevel || "XI";
    state.unit = state.lastViewed.unit;
    state.subtopic = state.lastViewed.subtopic;
    state.view = state.unit ? "formulas" : "home";
    $$(".subject-tab").forEach(b => b.classList.toggle("active", b.dataset.subject === state.subject));
    $$(".class-btn").forEach(b => b.classList.toggle("active", b.dataset.class === state.classLevel));
  }

  renderNavTree();
  renderContent();
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", () => setTimeout(init, 100));
} else {
  setTimeout(init, 100);
}
